module MdsPathResolveHasher
(
    input  wire clk,
    input  wire rstn,
    input  wire [512:0] fpath_data_last,
    input  wire         fpath_valid,
    output wire         fpath_ready,
    output wire [128:0] phash_data_last,
    output wire         phash_avail,
    input  wire         phash_pop
);
    wire [127:0] phash_data;
    wire phash_last;

    path_resolve_hasher ph_inst (
        .ap_clk             (clk),
        .ap_rst_n           (rstn),
        .s_path_data_TDATA  (fpath_data_last[511:0]),
        .s_path_data_TVALID (fpath_valid),
        .s_path_data_TREADY (fpath_ready),
        .s_path_data_TKEEP  (64'hffffffff_ffffffff),
        .s_path_data_TSTRB  (64'hffffffff_ffffffff),
        .s_path_data_TLAST  (fpath_data_last[512]),
        .m_hash_out_TDATA   (phash_data),
        .m_hash_out_TVALID  (phash_avail),
        .m_hash_out_TREADY  (phash_pop),
        .m_hash_out_TKEEP   (),
        .m_hash_out_TSTRB   (),
        .m_hash_out_TLAST   (phash_last)
    );

    assign phash_data_last = {phash_last, phash_data};

endmodule